# Section of every Z5 overlay row, read from the image section table.
# The three bytes 0x610bf5e3-0x610bf5e5 are the inherited central-edge call site.
# Any other row in section 6 or 7 fails.
# Do not edit this file after it has run.
import csv
import json
import struct
from pathlib import Path

ROOT = Path('.')
IMAGE = ROOT / 'inputs/00_0100_50000020.decoded.bin'
SRC = ROOT / 'ref/analysis/button-af/readiness/t5-afon-button-handoff/out/overlay-changed-bytes.csv'
OUT_CSV = ROOT / 'work/out/overlay-changed-bytes.csv'
OUT_JSON = ROOT / 'work/out/section-rows-l0.json'

BASE_PAGE_OFFSET = 0x020
FLASH_VIEW = 0x50000000
SECTION_ROW = 12
SECTION_LOAD = [0xf1, 0xe3, 0x8f, 0xff, 0xe3, 0xcd, None, None, 0x00, 0x00, 0x82, 0x8c, 0x14, 0xf9, 0x14, 0x0c, 0xf1, 0xe2, 0xfc, 0xd2]
SECTION_SWITCH = [0x04, 0xa0, 0x01, 0xc0, None, 0xa0, None, 0xc1, None, 0x28, 0xff, 0x54, 0xfc, 0xdc, None, None, None, None, 0xf3, 0x80, 0xf0, 0xf4]
PERMITTED_SECTION7 = {0x610bf5e3, 0x610bf5e4, 0x610bf5e5}
PERMITTED_MARK = 'section 7, EMULATOR-ONLY runtime call-site patch (inherited central-edge)'


def u32(buf, off):
    return struct.unpack_from('<I', buf, off)[0]


def cached(addr):
    if 0xA0000000 <= addr < 0xC0000000:
        return (addr - 0x40000000) & 0xFFFFFFFF
    return addr & 0xFFFFFFFF


def bytes_at(buf, off, pat):
    if off < 0 or off + len(pat) > len(buf):
        return False
    return all(p is None or buf[off + i] == p for i, p in enumerate(pat))


def one_at(buf, pat):
    hits = []
    start = 0
    first = pat[0]
    while True:
        o = buf.find(bytes([first]), start)
        if o < 0 or o + len(pat) > len(buf):
            break
        if bytes_at(buf, o, pat):
            hits.append(o)
        start = o + 1
    if len(hits) != 1:
        raise SystemExit(f'section load pattern hits {len(hits)}, want 1')
    return hits[0]


def call_at(buf, o):
    op = buf[o]
    if op == 0xdd:
        disp = struct.unpack_from('<i', buf, o + 1)[0]
        return o + disp
    if op == 0xcd:
        disp = struct.unpack_from('<h', buf, o + 1)[0]
        return o + disp
    if op == 0xfc and buf[o + 1] == 0xff:
        disp = struct.unpack_from('<i', buf, o + 2)[0]
        return o + disp
    if op == 0xfa and buf[o + 1] == 0xff:
        disp = struct.unpack_from('<h', buf, o + 2)[0]
        return o + disp
    raise SystemExit(f'not a call at file offset {o:#x}')


def image_base(buf):
    hits = []
    limit = min(0x400, len(buf) - 8)
    for o in range(limit + 1):
        if buf[o] == 0xfc and buf[o + 1] == 0xdc and buf[o + 6] == 0xf0 and buf[o + 7] == 0xf4:
            hits.append(o)
    if len(hits) != 1:
        raise SystemExit(f'image base jumps {len(hits)}, want 1')
    target = u32(buf, hits[0] + 2)
    if (target & 0xfff) < BASE_PAGE_OFFSET:
        raise SystemExit(f'image base target {target:#x} is below the page offset')
    return (target & ~0xfff) | BASE_PAGE_OFFSET


def section_ends(buf, base, switch_off):
    if not bytes_at(buf, switch_off, SECTION_SWITCH):
        raise SystemExit(f'section end switch at {switch_off:#x} does not match')
    count = buf[switch_off + 6]
    jt = u32(buf, switch_off + 14) - base
    ends = []
    for n in range(1, count + 1):
        case_off = u32(buf, jt + 4 * (n - 1)) - base
        if not (0 <= case_off and case_off + 6 <= len(buf)):
            raise SystemExit(f'section {n} case is outside the image')
        if buf[case_off] != 0xfc or buf[case_off + 1] != 0xcc:
            raise SystemExit(f'section {n} case is not mov imm32,d0')
        ends.append(u32(buf, case_off + 2))
    return ends


def load_sections(buf, base):
    at = one_at(buf, SECTION_LOAD)
    table = u32(buf, at + 20)
    switch_off = call_at(buf, at + 5)
    ends = section_ends(buf, base, switch_off)
    rows = []
    table_off = table - base
    for i, end in enumerate(ends):
        row = table_off + SECTION_ROW * i
        start = u32(buf, row)
        src = u32(buf, row + 4)
        flag = u32(buf, row + 8)
        file_off = src - FLASH_VIEW - BASE_PAGE_OFFSET
        if start != (base + file_off) & 0xFFFFFFFF:
            raise SystemExit(f'section {i + 1} does not copy in place: start {start:#x}')
        if not (start <= end <= base + len(buf)):
            raise SystemExit(f'section {i + 1} end {end:#x} is outside')
        rows.append({'n': i + 1, 'start': start, 'end': end, 'flag': flag, 'compressed': flag == 1})
    return rows


def section_of(sections, addr):
    c = cached(addr)
    for row in sections:
        if row['start'] <= c < row['end']:
            return row
    return None


def main():
    image = IMAGE.read_bytes()
    sections = load_sections(image, image_base(image))
    with SRC.open(newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        fieldnames = list(reader.fieldnames) + ['section']
        rows = list(reader)
    problems = []
    counts = {}
    seen = set()
    for rec in rows:
        addr = int(rec['runtime_address'], 16)
        off = int(rec['component_offset'], 16)
        stock = int(rec['stock_byte'], 16)
        if addr in seen:
            problems.append(f'duplicate {addr:#x}')
        seen.add(addr)
        if off >= len(image) or image[off] != stock:
            problems.append(f'stock mismatch at {addr:#x}')
        sec = section_of(sections, addr)
        if sec is None:
            problems.append(f'{addr:#x} is in no loaded section')
            rec['section'] = 'none'
            continue
        counts[sec['n']] = counts.get(sec['n'], 0) + 1
        if addr in PERMITTED_SECTION7:
            if sec['n'] != 7:
                problems.append(f'permitted call site {addr:#x} is section {sec["n"]}')
            rec['section'] = PERMITTED_MARK
        else:
            if sec['n'] in (6, 7):
                problems.append(f'{addr:#x} is in section {sec["n"]}')
            rec['section'] = str(sec['n'])
    found = {int(r['runtime_address'], 16) for r in rows}
    missing = sorted(PERMITTED_SECTION7 - found)
    if missing:
        problems.append('missing permitted call-site rows')
    report = {'rows': len(rows), 'counts': counts, 'problems': problems, 'ok': not problems}
    OUT_JSON.write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')
    if problems:
        print(json.dumps(report, indent=2))
        raise SystemExit(1)
    with OUT_CSV.open('w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames, lineterminator='\n')
        writer.writeheader()
        writer.writerows(rows)
    print(json.dumps(report))


if __name__ == '__main__':
    main()
